using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;

public class GemQuestGame : MonoBehaviour
{
    // Enums
    private enum GemColor { Red, Green, Blue, Yellow, Purple, Orange }
    private enum GameState { Start, Playing, Paused, Completed }

    // Data structures
    private class Gem
    {
        public GemColor Color;
        public bool IsObstacle;
        public bool IsLocked;
        public Vector2Int Position;
        public GameObject Instance; // Visual instance
    }

    private struct MatchInfo
    {
        public GemColor Color;
        public int Count;
        public int Combo;
        public List<Vector2Int> Positions;
    }

    [Header("Grid Settings")]
    public int rows = 8;
    public int cols = 8;
    public float gemSpacing = 1.1f;

    [Header("Prefabs")]
    public GameObject[] gemPrefabs; // 0‑5 for colors
    public GameObject obstaclePrefab;
    public ParticleSystem matchParticlePrefab;

    [Header("UI Elements")]
    public Text scoreText;
    public Text xpText;
    public Text levelText;
    public Text statusText;

    // Internal state
    private Gem[,] gemGrid;
    private GameState currentState = GameState.Start;
    private int score = 0;
    private int xp = 0;
    private int level = 1;
    private int combo = 1;
    private int difficultyLevel = 1;

    private void Start()
    {
        LoadGame();
        SetupLevel();
        currentState = GameState.Playing;
        statusText.text = "Playing";
    }

    #region Level Generation
    private void SetupLevel()
    {
        difficultyLevel = Mathf.CeilToInt((float)level / 5f);
        int obstacleChance = 15 + (difficultyLevel - 1) * 5; // percent
        gemGrid = new Gem[rows, cols];
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                bool isObstacle = Random.Range(0, 100) < obstacleChance;
                Gem gem = new Gem();
                gem.Position = new Vector2Int(r, c);
                gem.IsObstacle = isObstacle;
                gem.IsLocked = false;
                if (isObstacle)
                {
                    gem.Color = GemColor.Red; // placeholder
                    gem.Instance = Instantiate(obstaclePrefab, PositionToWorld(r, c), Quaternion.identity, transform);
                }
                else
                {
                    gem.Color = (GemColor)Random.Range(0, System.Enum.GetValues(typeof(GemColor)).Length);
                    gem.Instance = Instantiate(gemPrefabs[(int)gem.Color], PositionToWorld(r, c), Quaternion.identity, transform);
                }
                gemGrid[r, c] = gem;
            }
        }
        // Ensure no starting matches
        int attempts = 0;
        while (HasMatch() || !IsSwapPossible() && attempts < 10)
        {
            attempts++;
            RandomizeGrid();
        }
        UpdateUI();
    }

    private void RandomizeGrid()
    {
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (!gemGrid[r, c].IsObstacle)
                {
                    gemGrid[r, c].Color = (GemColor)Random.Range(0, System.Enum.GetValues(typeof(GemColor)).Length);
                }
            }
        }
    }

    private bool HasMatch()
    {
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (gemGrid[r, c].IsObstacle) continue;
                if (CheckMatchAt(r, c)) return true;
            }
        }
        return false;
    }

    private bool CheckMatchAt(int r, int c)
    {
        GemColor col = gemGrid[r, c].Color;
        // Horizontal
        int horizCount = 1;
        int cc = c - 1;
        while (cc >= 0 && !gemGrid[r, cc].IsObstacle && gemGrid[r, cc].Color == col) { horizCount++; cc--; }
        cc = c + 1;
        while (cc < cols && !gemGrid[r, cc].IsObstacle && gemGrid[r, cc].Color == col) { horizCount++; cc++; }
        if (horizCount >= 3) return true;
        // Vertical
        int vertCount = 1;
        int rr = r - 1;
        while (rr >= 0 && !gemGrid[rr, c].IsObstacle && gemGrid[rr, c].Color == col) { vertCount++; rr--; }
        rr = r + 1;
        while (rr < rows && !gemGrid[rr, c].IsObstacle && gemGrid[rr, c].Color == col) { vertCount++; rr++; }
        if (vertCount >= 3) return true;
        return false;
    }

    private bool IsSwapPossible()
    {
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (gemGrid[r, c].IsObstacle) continue;
                // Right neighbor
                if (c + 1 < cols && !gemGrid[r, c + 1].IsObstacle)
                {
                    SwapInternal(r, c, r, c + 1);
                    if (CheckMatchAt(r, c) || CheckMatchAt(r, c + 1))
                    {
                        SwapInternal(r, c, r, c + 1); // revert
                        return true;
                    }
                    SwapInternal(r, c, r, c + 1); // revert
                }
                // Down neighbor
                if (r + 1 < rows && !gemGrid[r + 1, c].IsObstacle)
                {
                    SwapInternal(r, c, r + 1, c);
                    if (CheckMatchAt(r, c) || CheckMatchAt(r + 1, c))
                    {
                        SwapInternal(r, c, r + 1, c); // revert
                        return true;
                    }
                    SwapInternal(r, c, r + 1, c); // revert
                }
            }
        }
        return false;
    }

    private Vector3 PositionToWorld(int r, int c)
    {
        return new Vector3(c * gemSpacing, 0, r * gemSpacing);
    }

    #endregion

    #region Swapping
    private void OnGemSelected(Vector2Int pos)
    {
        if (currentState != GameState.Playing) return;
        // Input handling omitted for brevity
    }

    private void AttemptSwap(Vector2Int a, Vector2Int b)
    {
        if (!IsAdjacent(a, b)) return;
        if (gemGrid[a.x, a.y].IsObstacle || gemGrid[b.x, b.y].IsObstacle) return;
        SwapInternal(a.x, a.y, b.x, b.y);
        if (HasMatch())
        {
            ResolveMatches();
        }
        else
        {
            StartCoroutine(RevertSwap(a, b));
        }
    }

    private bool IsAdjacent(Vector2Int a, Vector2Int b)
    {
        int dx = Mathf.Abs(a.x - b.x);
        int dy = Mathf.Abs(a.y - b.y);
        return (dx + dy) == 1;
    }

    private void SwapInternal(int r1, int c1, int r2, int c2)
    {
        Gem temp = gemGrid[r1, c1];
        gemGrid[r1, c1] = gemGrid[r2, c2];
        gemGrid[r2, c2] = temp;
        gemGrid[r1, c1].Position = new Vector2Int(r1, c1);
        gemGrid[r2, c2].Position = new Vector2Int(r2, c2);
        gemGrid[r1, c1].Instance.transform.position = PositionToWorld(r1, c1);
        gemGrid[r2, c2].Instance.transform.position = PositionToWorld(r2, c2);
    }

    private IEnumerator RevertSwap(Vector2Int a, Vector2Int b)
    {
        yield return new WaitForSeconds(0.3f);
        SwapInternal(a.x, a.y, b.x, b.y);
    }

    #endregion

    #region Match Resolution
    private void ResolveMatches()
    {
        List<MatchInfo> matches = FindAllMatches();
        if (matches.Count == 0) return;
        foreach (var match in matches)
        {
            score += (int)(match.Count * combo * 1.5f);
            xp += match.Count * 10;
            // Trigger particles
            foreach (var pos in match.Positions)
            {
                ParticleSystem ps = Instantiate(matchParticlePrefab, PositionToWorld(pos.x, pos.y), Quaternion.identity);
                ps.Play();
                Destroy(ps.gameObject, ps.main.duration);
            }
            // Remove gems
            foreach (var pos in match.Positions)
            {
                Destroy(gemGrid[pos.x, pos.y].Instance);
                gemGrid[pos.x, pos.y] = null;
            }
        }
        UpdateUI();
        StartCoroutine(ApplyGravity());
    }

    private List<MatchInfo> FindAllMatches()
    {
        List<MatchInfo> result = new List<MatchInfo>();
        bool[,] visited = new bool[rows, cols];
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (visited[r, c] || gemGrid[r, c] == null || gemGrid[r, c].IsObstacle) continue;
                List<Vector2Int> line = new List<Vector2Int>();
                // Horizontal
                int cc = c;
                while (cc < cols && gemGrid[r, cc] != null && gemGrid[r, cc].Color == gemGrid[r, c].Color) { line.Add(new Vector2Int(r, cc)); cc++; }
                if (line.Count >= 3)
                {
                    foreach (var p in line) visited[p.x, p.y] = true;
                    result.Add(new MatchInfo { Color = gemGrid[r, c].Color, Count = line.Count, Combo = combo, Positions = line });
                }
                // Vertical
                line.Clear();
                int rr = r;
                while (rr < rows && gemGrid[rr, c] != null && gemGrid[rr, c].Color == gemGrid[r, c].Color) { line.Add(new Vector2Int(rr, c)); rr++; }
                if (line.Count >= 3)
                {
                    foreach (var p in line) visited[p.x, p.y] = true;
                    result.Add(new MatchInfo { Color = gemGrid[r, c].Color, Count = line.Count, Combo = combo, Positions = line });
                }
            }
        }
        combo++; // Increase for potential chain
        return result;
    }

    private IEnumerator ApplyGravity()
    {
        bool moved = false;
        for (int c = 0; c < cols; c++)
        {
            for (int r = rows - 1; r >= 0; r--)
            {
                if (gemGrid[r, c] == null)
                {
                    int rr = r - 1;
                    while (rr >= 0 && gemGrid[rr, c] == null) rr--;
                    if (rr >= 0)
                    {
                        gemGrid[r, c] = gemGrid[rr, c];
                        gemGrid[r, c].Position = new Vector2Int(r, c);
                        gemGrid[r, c].Instance.transform.position = PositionToWorld(r, c);
                        gemGrid[rr, c] = null;
                        moved = true;
                    }
                }
            }
        }
        if (moved)
        {
            yield return new WaitForSeconds(0.2f);
            StartCoroutine(ApplyGravity());
        }
        else
        {
            FillEmpty();
        }
    }

    private void FillEmpty()
    {
        for (int c = 0; c < cols; c++)
        {
            for (int r = 0; r < rows; r++)
            {
                if (gemGrid[r, c] == null && !IsObstacleAt(r, c))
                {
                    Gem gem = new Gem();
                    gem.Color = (GemColor)Random.Range(0, System.Enum.GetValues(typeof(GemColor)).Length);
                    gem.Position = new Vector2Int(r, c);
                    gem.Instance = Instantiate(gemPrefabs[(int)gem.Color], PositionToWorld(r, c), Quaternion.identity, transform);
                    gemGrid[r, c] = gem;
                }
            }
        }
        if (HasMatch()) ResolveMatches();
    }

    private bool IsObstacleAt(int r, int c)
    {
        return false; // obstacles are already placed as non‑null in grid
    }

    #endregion

    #region UI & State
    private void UpdateUI()
    {
        scoreText.text = $\"Score: {score}\";
        xpText.text = $\"XP: {xp}\";
        levelText.text = $\"Level: {level}\";
    }

    private void LoadGame()
    {
        if (PlayerPrefs.HasKey("currentLevel"))
        {
            level = PlayerPrefs.GetInt("currentLevel");
            score = PlayerPrefs.GetInt("score");
            xp = PlayerPrefs.GetInt("xp");
        }
    }

    private void SaveGame()
    {
        PlayerPrefs.SetInt("currentLevel", level);
        PlayerPrefs.SetInt("score", score);
        PlayerPrefs.SetInt("xp", xp);
        PlayerPrefs.Save();
    }

    private void OnApplicationQuit()
    {
        SaveGame();
    }
    #endregion
}

