            xp += match.Count * 10;
            // Trigger particles
            foreach (var pos in match.Positions)
            {
                ParticleSystem ps = Instantiate(matchParticlePrefab, PositionToWorld(pos.x, pos.y), Quaternion.identity);
                ps.Play();
                Destroy(ps.gameObject, ps.main.duration);
            }
            // Remove gems
            foreach (var pos in match.Positions)
            {
                Destroy(gemGrid[pos.x, pos.y].Instance);
                gemGrid[pos.x, pos.y] = null;
            }
        }
        UpdateUI();
        StartCoroutine(ApplyGravity());
    }

    private List<MatchInfo> FindAllMatches()
    {
        List<MatchInfo> result = new List<MatchInfo>();
        bool[,] visited = new bool[rows, cols];
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (visited[r, c] || gemGrid[r, c] == null || gemGrid[r, c].IsObstacle) continue;
                List<Vector2Int> line = new List<Vector2Int>();
                // Horizontal
                int cc = c;
                while (cc < cols && gemGrid[r, cc] != null && gemGrid[r, cc].Color == gemGrid[r, c].Color) { line.Add(new Vector2Int(r, cc)); cc++; }
                if (line.Count >= 3)
                {
                    foreach (var p in line) visited[p.x, p.y] = true;
                    result.Add(new MatchInfo { Color = gemGrid[r, c].Color, Count = line.Count, Combo = combo, Positions = line });
                }
                // Vertical
                line.Clear();
                int rr = r;
                while (rr < rows && gemGrid[rr, c] != null && gemGrid[rr, c].Color == gemGrid[r, c].Color) { line.Add(new Vector2Int(rr, c)); rr++; }
                if (line.Count >= 3)
                {
                    foreach (var p in line) visited[p.x, p.y] = true;
                    result.Add(new MatchInfo { Color = gemGrid[r, c].Color, Count = line.Count, Combo = combo, Positions = line });
                }
            }
        }
        combo++; // Increase for potential chain
        return result;
    }

    private IEnumerator ApplyGravity()
    {
        bool moved = false;
        for (int c = 0; c < cols; c++)
        {
            for (int r = rows - 1; r >= 0; r--)
            {
                if (gemGrid[r, c] == null)
                {
                    int rr = r - 1;
                    while (rr >= 0 && gemGrid[rr, c] == null) rr--;
                    if (rr >= 0)
                    {
                        gemGrid[r, c] = gemGrid[rr, c];
                        gemGrid[r, c].Position = new Vector2Int(r, c);
                        gemGrid[r, c].Instance.transform.position = PositionToWorld(r, c);
                        gemGrid[rr, c] = null;
                        moved = true;
                    }
                }
            }
        }
        if (moved)
        {
            yield return new WaitForSeconds(0.2f);
            StartCoroutine(ApplyGravity());
        }
        else
        {
            FillEmpty();
        }
    }

    private void FillEmpty()
    {
        for (int c = 0; c < cols; c++)
        {
            for (int r = 0; r < rows; r++)
            {
                if (gemGrid[r, c] == null && !IsObstacleAt(r, c))
                {
                    Gem gem = new Gem();
                    gem.Color = (GemColor)Random.Range(0, System.Enum.GetValues(typeof(GemColor)).Length);
                    gem.Position = new Vector2Int(r, c);
                    gem.Instance = Instantiate(gemPrefabs[(int)gem.Color], PositionToWorld(r, c), Quaternion.identity, transform);
                    gemGrid[r, c] = gem;
                }
            }
        }
        if (HasMatch()) ResolveMatches();
    }

